$ErrorActionPreference="Stop"; Set-Location C:\stock-bot; $Python="C:\stock-bot\.venv\Scripts\python.exe"; $Port=8877
$old=@(Get-NetTCPConnection -LocalPort $Port -State Listen -ErrorAction SilentlyContinue); foreach($L in $old){Stop-Process -Id $L.OwningProcess -Force -ErrorAction SilentlyContinue}
$P=Start-Process -FilePath $Python -ArgumentList @("C:\stock-bot\dashboard\operations_dashboard_v3_2.py","--root","C:\stock-bot","--host","127.0.0.1","--port","$Port") -WorkingDirectory C:\stock-bot -PassThru
try{Start-Sleep 5; $S=Invoke-RestMethod "http://127.0.0.1:$Port/api/status"; $R=$S.trade_analytics.cross_ledger_reconstruction; Write-Host "VISUALIZATION STATUS:" $S.visualization_status; Write-Host "TRADE ANALYTICS STATUS:" $S.trade_analytics_status; Write-Host "FILL RECORDS:" $R.fill_record_count; Write-Host "FILL SOURCES:" $R.fill_source_count; Write-Host "RECONSTRUCTED TRADES:" $R.reconstructed_trade_count; Write-Host "UNRESOLVED TRADES:" $R.unresolved_trade_count; Write-Host "CONFIDENCE:" ($R.confidence_counts|ConvertTo-Json -Compress); Write-Host "UNRESOLVED REASONS:" ($R.unresolved_reason_counts|ConvertTo-Json -Compress); Write-Host "RECONSTRUCTION STATUS:" $R.status; if($S.visualization_status -ne "PASS"){throw "VISUALIZATION REGRESSION"}; if($S.trade_analytics_status -like "ISOLATED_*"){throw "ANALYTICS ERROR"}; if(-not $R.contracts.actual_fill_records_only){throw "FILL CONTRACT FAILED"}; if($R.contracts.price_guessing_used){throw "PRICE GUESSING DETECTED"}; Write-Host "VERIFY: PASS"} finally{Stop-Process -Id $P.Id -Force -ErrorAction SilentlyContinue}
